import{_ as s}from"./plugin-vue_export-helper-c27b6911.js";import{o as a,c as n,d as e}from"./app-c5e09484.js";const l={},o=e(`<h1 id="基础" tabindex="-1"><a class="header-anchor" href="#基础" aria-hidden="true">#</a> 基础</h1><p>首先，程序启动时会从 <strong>初始脚本</strong> <code>start.txt</code> 开始运行，请不要重命名或者删除。</p><p>后面的教程中将会教你如何使用 WebGAL 脚本。</p><h2 id="注释" tabindex="-1"><a class="header-anchor" href="#注释" aria-hidden="true">#</a> 注释</h2><p>WebGAL 脚本只会解析每一行的分号前的内容，因此分号后的内容会被视作注释。</p><div class="language-webgal line-numbers-mode" data-ext="webgal"><pre class="shiki dracula" style="background-color:#282A36;" tabindex="0"><code><span class="line"><span style="color:#FFB86C;">WebGAL</span><span style="color:#FF5555;">:</span><span style="color:#F1FA8C;">你好！</span><span style="color:#6272A4;">; 分号后的内容会被视作注释</span></span>
<span class="line"><span style="color:#6272A4;">; 可以直接输入一个分号，然后写一条单行注释</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="多行语句" tabindex="-1"><a class="header-anchor" href="#多行语句" aria-hidden="true">#</a> 多行语句</h2><p>一条语句的参数太多时，可以把它写成多行，便于阅读。</p><p><strong>续行必须以空白字符开头，且去掉空白后的第一个字符是 <code>-</code> 或 <code>|</code>。</strong> 满足这个条件的行会被接到上一条语句的末尾，整体仍然是一条语句。</p><div class="language-webgal line-numbers-mode" data-ext="webgal"><pre class="shiki dracula" style="background-color:#282A36;" tabindex="0"><code><span class="line"><span style="color:#8BE9FD;">changeFigure</span><span style="color:#FF5555;">:</span><span style="color:#F8F8F2;">stand.webp</span></span>
<span class="line"><span style="color:#F1FA8C;"> </span><span style="color:#F8F8F2;"> </span><span style="color:#FF5555;">-</span><span style="color:#FFB86C;">left</span></span>
<span class="line"><span style="color:#F1FA8C;"> </span><span style="color:#F8F8F2;"> </span><span style="color:#FF5555;">-</span><span style="color:#FFB86C;">id</span><span style="color:#FF5555;">=</span><span style="color:#50FA7B;">fig1</span></span>
<span class="line"><span style="color:#F1FA8C;"> </span><span style="color:#F8F8F2;"> </span><span style="color:#FF5555;">-</span><span style="color:#FFB86C;">next</span><span style="color:#6272A4;">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>上面这段等价于：</p><div class="language-webgal line-numbers-mode" data-ext="webgal"><pre class="shiki dracula" style="background-color:#282A36;" tabindex="0"><code><span class="line"><span style="color:#8BE9FD;">changeFigure</span><span style="color:#FF5555;">:</span><span style="color:#F8F8F2;">stand.webp </span><span style="color:#FF5555;">-</span><span style="color:#FFB86C;">left</span><span style="color:#F8F8F2;"> </span><span style="color:#FF5555;">-</span><span style="color:#FFB86C;">id</span><span style="color:#FF5555;">=</span><span style="color:#50FA7B;">fig1</span><span style="color:#F8F8F2;"> </span><span style="color:#FF5555;">-</span><span style="color:#FFB86C;">next</span><span style="color:#6272A4;">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p><code>intro</code> 的多段文字同样可以用 <code>|</code> 续行：</p><div class="language-webgal line-numbers-mode" data-ext="webgal"><pre class="shiki dracula" style="background-color:#282A36;" tabindex="0"><code><span class="line"><span style="color:#8BE9FD;">intro</span><span style="color:#FF5555;">:</span><span style="color:#F8F8F2;">第一段文字</span></span>
<span class="line"><span style="color:#F1FA8C;">  |第二段文字</span></span>
<span class="line"><span style="color:#F1FA8C;">  |第三段文字</span><span style="color:#F8F8F2;"> </span><span style="color:#FF5555;">-</span><span style="color:#FFB86C;">hold</span><span style="color:#6272A4;">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>图形编辑器在语句过长时会自动按这种格式输出多行；语句较短时仍然保持单行。</p><h3 id="需要注意的规则" tabindex="-1"><a class="header-anchor" href="#需要注意的规则" aria-hidden="true">#</a> 需要注意的规则</h3><ul><li><strong>分号和行内注释只能写在最后一行。</strong> 分号之后的内容会被当作注释，写在首行会把后面的续行一起吞掉。</li><li><strong>空行会终止多行语句。</strong> 想让一条语句跨多行，中间不要留空行。</li><li><strong>含 <code>-concat</code> 的语句不会自动续行。</strong> 因为 <code>-concat</code> 本身用于把对话接在上一句之后，两者的语义会冲突。</li><li><strong>行尾写反斜杠 <code>\\</code> 可以强制续行</strong>，用于绕过上面的限制：</li></ul><div class="language-webgal line-numbers-mode" data-ext="webgal"><pre class="shiki dracula" style="background-color:#282A36;" tabindex="0"><code><span class="line"><span style="color:#8BE9FD;">intro</span><span style="color:#FF5555;">:</span><span style="color:#F8F8F2;">第一段文字\\</span></span>
<span class="line"><span style="color:#F1FA8C;">|第二段文字\\</span></span>
<span class="line"><span style="color:#F1FA8C;">|第三段文字</span><span style="color:#F8F8F2;"> </span><span style="color:#FF5555;">-</span><span style="color:#FFB86C;">concat</span><span style="color:#6272A4;">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><ul><li><strong>兼容性提示：</strong> 以「空格 + <code>-</code>」开头的对白会被误认为续行。如果你确实要让对白以破折号开头，请去掉行首空格，或在行首加上其他字符。</li></ul><h2 id="特殊符号转义" tabindex="-1"><a class="header-anchor" href="#特殊符号转义" aria-hidden="true">#</a> 特殊符号转义</h2><p>WebGAL 脚本使用英文冒号 <code>:</code> 分隔命令和内容，使用英文分号 <code>;</code> 结束语句并开始行内注释，部分命令还会使用 <code>|</code>、<code>,</code>、<code>.</code> 等符号作为内容语法的一部分。如果你希望这些符号作为普通文本显示，可以在符号前加反斜杠 <code>\\</code>。</p><p>常见需要转义的符号：</p><table><thead><tr><th style="text-align:left;">原符号</th><th style="text-align:left;">写法</th></tr></thead><tbody><tr><td style="text-align:left;"><code>:</code></td><td style="text-align:left;"><code>\\:</code></td></tr><tr><td style="text-align:left;"><code>,</code></td><td style="text-align:left;"><code>\\,</code></td></tr><tr><td style="text-align:left;"><code>.</code></td><td style="text-align:left;"><code>\\.</code></td></tr><tr><td style="text-align:left;"><code>;</code></td><td style="text-align:left;"><code>\\;</code></td></tr><tr><td style="text-align:left;">\`</td><td style="text-align:left;">\`</td></tr></tbody></table><div class="language-webgal line-numbers-mode" data-ext="webgal"><pre class="shiki dracula" style="background-color:#282A36;" tabindex="0"><code><span class="line"><span style="color:#8BE9FD;">intro</span><span style="color:#FF5555;">:</span><span style="color:#F8F8F2;">我会显示出来：\\:\\,\\.\\</span><span style="color:#6272A4;">;不信你看看 -hold;</span></span>
<span class="line"><span style="color:#FFB86C;">WebGAL</span><span style="color:#FF5555;">:</span><span style="color:#F1FA8C;">我会显示出来：\\:\\,\\.\\</span><span style="color:#6272A4;">;不信你看看;</span></span>
<span class="line"><span style="color:#8BE9FD;">choose</span><span style="color:#FF5555;">:</span><span style="color:#F8F8F2;">我会显示出来：\\:\\,\\.\\</span><span style="color:#6272A4;">;不信你看看:nextLabel;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>在文本拓展语法中写 CSS 时，分号同样需要写成 <code>\\;</code>，否则会被当作 WebGAL 语句注释的开始。</p><h2 id="none-关键词" tabindex="-1"><a class="header-anchor" href="#none-关键词" aria-hidden="true">#</a> <code>none</code> 关键词</h2><p>在设置立绘、BGM、背景等 <strong>资源</strong> 时，通过设置为 <code>none</code>，可以关闭这个对象。</p><h2 id="next-参数" tabindex="-1"><a class="header-anchor" href="#next-参数" aria-hidden="true">#</a> <code>-next</code> 参数</h2><p>你可以在任意语句后加上参数 <code>-next</code>，这样做可以在执行完本条语句后立刻跳转到下一条语句。这对需要在同一时间内执行多步操作非常有用。</p><p>示例：</p><div class="language-webgal line-numbers-mode" data-ext="webgal"><pre class="shiki dracula" style="background-color:#282A36;" tabindex="0"><code><span class="line"><span style="color:#8BE9FD;">changeBg</span><span style="color:#FF5555;">:</span><span style="color:#F8F8F2;">testBG03.jpg </span><span style="color:#FF5555;">-</span><span style="color:#FFB86C;">next</span><span style="color:#6272A4;">; // 会立刻执行下一条语句</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><h2 id="notend-和-concat-参数" tabindex="-1"><a class="header-anchor" href="#notend-和-concat-参数" aria-hidden="true">#</a> <code>-notend</code> 和 <code>-concat</code> 参数</h2><p>有时候，可能你希望在某一句对话执行到某个阶段时加入演出效果，比如切换表情等。<br> 这时候，你可以使用 <code>-notend</code> <code>-concat</code> 参数来实现在对话中插入任意语句。</p><p><code>-concat</code> 代表本句对话连接在上一句对话之后</p><p><code>-notend</code> 代表本句对话没有结束，在后面可能连接演出或对话。</p><p>示例如下：这是一个在对话进行中切换立绘的演示。</p><div class="language-webgal line-numbers-mode" data-ext="webgal"><pre class="shiki dracula" style="background-color:#282A36;" tabindex="0"><code><span class="line"><span style="color:#FFB86C;">WebGAL</span><span style="color:#FF5555;">:</span><span style="color:#F1FA8C;">测试语句插演出！马上切换立绘......</span><span style="color:#F8F8F2;"> </span><span style="color:#FF5555;">-</span><span style="color:#FFB86C;">notend</span><span style="color:#6272A4;">;</span></span>
<span class="line"><span style="color:#8BE9FD;">changeFigure</span><span style="color:#FF5555;">:</span><span style="color:#F8F8F2;">k1.png </span><span style="color:#FF5555;">-</span><span style="color:#FFB86C;">next</span><span style="color:#6272A4;">;</span></span>
<span class="line"><span style="color:#F1FA8C;">切换立绘！马上切换表情......</span><span style="color:#F8F8F2;"> </span><span style="color:#FF5555;">-</span><span style="color:#FFB86C;">notend</span><span style="color:#F8F8F2;"> </span><span style="color:#FF5555;">-</span><span style="color:#FFB86C;">concat</span><span style="color:#6272A4;">;</span></span>
<span class="line"><span style="color:#8BE9FD;">changeFigure</span><span style="color:#FF5555;">:</span><span style="color:#F8F8F2;">k2.png </span><span style="color:#FF5555;">-</span><span style="color:#FFB86C;">next</span><span style="color:#6272A4;">;</span></span>
<span class="line"><span style="color:#F1FA8C;">切换表情！</span><span style="color:#F8F8F2;"> </span><span style="color:#FF5555;">-</span><span style="color:#FFB86C;">concat</span><span style="color:#6272A4;">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>你也可以只使用 <code>-concat</code> 参数，将下一句连接在上一句对话之后，因为 <code>-notend</code> 参数会在对话渐显完成后转到下一句。</p><div class="language-webgal line-numbers-mode" data-ext="webgal"><pre class="shiki dracula" style="background-color:#282A36;" tabindex="0"><code><span class="line"><span style="color:#F1FA8C;">这是第一句......</span><span style="color:#6272A4;">;</span></span>
<span class="line"><span style="color:#F1FA8C;">用户点击鼠标后才会转到第二句</span><span style="color:#F8F8F2;"> </span><span style="color:#FF5555;">-</span><span style="color:#FFB86C;">concat</span><span style="color:#6272A4;">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div>`,39),c=[o];function p(t,d){return a(),n("div",null,c)}const F=s(l,[["render",p],["__file","base.html.vue"]]);export{F as default};
